import { ethers } from "ethers";

/**
 * Helper to safely checksum addresses regardless of input casing.
 */
function getChecksumAddress(addr: string): string {
  try {
    return ethers.getAddress(addr.toLowerCase());
  } catch {
    return addr;
  }
}

